-- Lot 201 : payloads 1 a 30 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-001","moteur":"chatgpt","payload":"[RaccourcIA — /xray]\n\nMISSION\nRendre visible la structure interne plausible d'un objet. Superpose transparence froide et contours lumineux en gardant l’enveloppe reconnaissable. Les éléments internes non documentés restent conceptuels, sans valeur diagnostique.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Le rendu doit-il être pédagogique, conceptuel ou fondé uniquement sur des données techniques vérifiées ?. Accepte « Choisis pour moi », décide professionnellement et continue.\n\nEXÉCUTION\nSuperpose transparence froide et contours lumineux en gardant l’enveloppe reconnaissable. Les éléments internes non documentés restent conceptuels, sans valeur diagnostique. Format par défaut : 16:9, haute définition. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"ec9d0e2039857a01c55fe8a0b6c5f21433750bdf00b160ef8c7ba4b60b6bbda7"},{"ref":"RCI-IMG-001","moteur":"claude","payload":"[RaccourcIA — /xray]\n\nMISSION\nRendre visible la structure interne plausible d'un objet. Superpose transparence froide et contours lumineux en gardant l’enveloppe reconnaissable. Les éléments internes non documentés restent conceptuels, sans valeur diagnostique.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Le rendu doit-il être pédagogique, conceptuel ou fondé uniquement sur des données techniques vérifiées ?. Accepte « Choisis pour moi », décide professionnellement et continue.\n\nEXÉCUTION\nSuperpose transparence froide et contours lumineux en gardant l’enveloppe reconnaissable. Les éléments internes non documentés restent conceptuels, sans valeur diagnostique. Format par défaut : 16:9, haute définition. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"306ec5e3d09f7128fb1ac8567241362d8a478de04451fec8bdae8bd58e06830b"},{"ref":"RCI-IMG-001","moteur":"gemini","payload":"[RaccourcIA — /xray]\n\nMISSION\nRendre visible la structure interne plausible d'un objet. Superpose transparence froide et contours lumineux en gardant l’enveloppe reconnaissable. Les éléments internes non documentés restent conceptuels, sans valeur diagnostique.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Le rendu doit-il être pédagogique, conceptuel ou fondé uniquement sur des données techniques vérifiées ?. Accepte « Choisis pour moi », décide professionnellement et continue.\n\nEXÉCUTION\nSuperpose transparence froide et contours lumineux en gardant l’enveloppe reconnaissable. Les éléments internes non documentés restent conceptuels, sans valeur diagnostique. Format par défaut : 16:9, haute définition. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"d468a39bb58a21126c49110512774da7d0e94450855c50c29a4b4371b8a7ed6a"},{"ref":"RCI-IMG-002","moteur":"chatgpt","payload":"[RaccourcIA — /explodeview]\n\nMISSION\nDécomposer un objet en pieces logiques tout en gardant l'ordre d'assemblage. Écarte les pièces selon leurs axes d’assemblage, conserve ordre et proportions, ajoute des guides fins. Aucun composant interne ne peut être affirmé sans référence.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Le rendu doit-il être pédagogique, conceptuel ou fondé uniquement sur des données techniques vérifiées ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Vue éclatée » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Écarte les pièces selon leurs axes d’assemblage, conserve ordre et proportions, ajoute des guides fins. Aucun composant interne ne peut être affirmé sans référence. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"8432070e203b66dda2baaca917911fba6f7bd47e5ae8262173b3106523e8ef2a"},{"ref":"RCI-IMG-002","moteur":"claude","payload":"[RaccourcIA — /explodeview]\n\nMISSION\nDécomposer un objet en pieces logiques tout en gardant l'ordre d'assemblage. Écarte les pièces selon leurs axes d’assemblage, conserve ordre et proportions, ajoute des guides fins. Aucun composant interne ne peut être affirmé s